#!/usr/bin/env bun
/**
 * Rebuildable image fixtures for the HEIC verification workflows.
 *
 * These live in the repository (not in `.cache`) so the HEIC acceptance can be
 * reproduced from a clean checkout: everything here is generated by real
 * encoders — libheif through pillow-heif for HEIC, libvips through sharp for
 * AVIF — and every derived sample is produced by editing a real container, never
 * by hand-writing a header.
 *
 * Usage:
 *   bun run scripts/verification/upgrade-0153-fixtures.ts [--out=<dir>]
 *
 * Samples:
 *   photo.heic            2048x1536, the size a phone photo actually has
 *   photo.avif            same source, real AVIF (carries the generic mif1 brand)
 *   decoy-ispe.heic       real HEIC with a `free` box holding a fake ispe 1x1
 *   oversized-ispe.heic   real HEIC whose own ispe is patched to 20000x20000
 *   missing-ispe.heic     real HEIC with the ispe property type renamed
 *   truncated.heic        real HEIC cut to a third of its length
 *   control.jpg           JPEG control (must never be treated as HEIC)
 *   manifest.json         sha256, byte sizes, dimensions and the encoder command
 */
import { execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import sharp from 'sharp'

const root = resolve(import.meta.dir, '../..')
const arg = (name: string) => process.argv.slice(2).find(value => value.startsWith(`--${name}=`))?.slice(name.length + 3)
const out = resolve(root, arg('out') ?? '.cache/upgrade-20261018/fixtures')
mkdirSync(out, { recursive: true })

const sha256 = (buffer: Buffer) => createHash('sha256').update(buffer).digest('hex')

/** uv, preferring the binary this repo ships over whatever is on PATH. */
function resolveUv(): string {
  const platformKey = `${process.platform}-${process.arch}`
  const packaged = join(root, 'apps/electron/resources/bin', platformKey, process.platform === 'win32' ? 'uv.exe' : 'uv')
  if (existsSync(packaged)) return packaged
  return process.platform === 'win32' ? 'uv.exe' : 'uv'
}

const WIDTH = 2048
const HEIGHT = 1536
const source = join(out, 'source.png')

/** A photo-like source: gradient background plus shapes, so JPEG has real work. */
await sharp({
  create: { width: WIDTH, height: HEIGHT, channels: 3, background: { r: 18, g: 64, b: 120 } },
})
  .composite([
    { input: Buffer.from(
        `<svg width="${WIDTH}" height="${HEIGHT}" xmlns="http://www.w3.org/2000/svg">`
        + '<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1">'
        + '<stop offset="0" stop-color="#123f78"/><stop offset="1" stop-color="#e8a13a"/></linearGradient></defs>'
        + `<rect width="${WIDTH}" height="${HEIGHT}" fill="url(#g)"/>`
        + '<circle cx="700" cy="620" r="360" fill="#f8f4ec" opacity="0.85"/>'
        + '<rect x="1080" y="420" width="620" height="420" rx="48" fill="#1b1b22" opacity="0.7"/>'
        + `<text x="120" y="${HEIGHT - 120}" font-family="Arial" font-size="120" fill="#ffffff">HEIC fixture</text>`
        + '</svg>',
      ), top: 0, left: 0 },
  ])
  .png()
  .toFile(source)

const encodeCommand = [
  resolveUv(), 'run', '--python', '3.12.15', '--quiet', '-',
].join(' ')
const heic = join(out, 'photo.heic')
const python = execFileSync(resolveUv(), ['run', '--python', '3.12.15', '--quiet', '-'], {
  input: `
# /// script
# dependencies = ["Pillow==12.3.0", "pillow-heif==1.8.1"]
# ///
import pillow_heif
from PIL import Image
pillow_heif.register_heif_opener()
image = Image.open(${JSON.stringify(source)}).convert('RGB')
image.save(${JSON.stringify(heic)}, format='HEIF', quality=88)
print('pillow-heif', pillow_heif.__version__ if hasattr(pillow_heif, '__version__') else 'unknown')
`,
  encoding: 'utf8',
  stdio: ['pipe', 'pipe', 'inherit'],
  timeout: 600_000,
})
const heicBytes = readFileSync(heic)

// --- real AVIF from the same source ---------------------------------------
const avif = join(out, 'photo.avif')
await sharp(readFileSync(source)).avif({ quality: 55 }).toFile(avif)

// Smaller samples: below the pipeline's 1568px optimal edge, so they exercise the
// "transcode only, no resize" path (and, for AVIF, prove it is not touched).
const smallSource = join(out, 'small-source.png')
await sharp({ create: { width: 800, height: 600, channels: 3, background: { r: 40, g: 120, b: 90 } } })
  .composite([{ input: Buffer.from('<svg width="800" height="600" xmlns="http://www.w3.org/2000/svg"><circle cx="400" cy="300" r="240" fill="#f6f1e7"/></svg>'), top: 0, left: 0 }])
  .png()
  .toFile(smallSource)
const smallHeic = join(out, 'small.heic')
const smallAvif = join(out, 'small.avif')
execFileSync(resolveUv(), ['run', '--python', '3.12.15', '--quiet', '-'], {
  input: `
# /// script
# dependencies = ["Pillow==12.3.0", "pillow-heif==1.8.1"]
# ///
import pillow_heif
from PIL import Image
pillow_heif.register_heif_opener()
image = Image.open(${JSON.stringify(smallSource)}).convert('RGB')
image.save(${JSON.stringify(smallHeic)}, format='HEIF', quality=88)
print('small-heic-ok')
`,
  encoding: 'utf8',
  stdio: ['pipe', 'pipe', 'inherit'],
  timeout: 600_000,
})
await sharp(readFileSync(smallSource)).avif({ quality: 55 }).toFile(smallAvif)

// --- JPEG control ----------------------------------------------------------
const jpeg = join(out, 'control.jpg')
await sharp(readFileSync(source)).jpeg({ quality: 85 }).toFile(jpeg)

// --- derived HEIC samples --------------------------------------------------
/** Build a `free` box whose payload contains a literal `ispe` plus 1x1 dims. */
function decoyFreeBox(): Buffer {
  const payload = Buffer.concat([
    Buffer.from('ispe', 'latin1'),
    Buffer.alloc(4),            // version + flags
    Buffer.alloc(4),            // width  (patched below)
    Buffer.alloc(4),            // height (patched below)
  ])
  payload.writeUInt32BE(1, 8)
  payload.writeUInt32BE(1, 12)
  const header = Buffer.alloc(8)
  header.writeUInt32BE(8 + payload.length, 0)
  header.write('free', 4, 'latin1')
  return Buffer.concat([header, payload])
}

const ftypSize = heicBytes.readUInt32BE(0)
const decoy = Buffer.concat([heicBytes.subarray(0, ftypSize), decoyFreeBox(), heicBytes.subarray(ftypSize)])
writeFileSync(join(out, 'decoy-ispe.heic'), decoy)

/** In-place patch of the real `ispe` (no size change, so offsets stay valid). */
const oversized = Buffer.from(heicBytes)
const ispeAt = oversized.indexOf(Buffer.from('ispe', 'latin1'))
if (ispeAt < 0) throw new Error('fixture HEIC has no ispe to patch')
oversized.writeUInt32BE(20000, ispeAt + 8)
oversized.writeUInt32BE(20000, ispeAt + 12)
writeFileSync(join(out, 'oversized-ispe.heic'), oversized)

/** Rename the ispe property type so no usable dimensions remain. */
const missing = Buffer.from(heicBytes)
for (let at = missing.indexOf(Buffer.from('ispe', 'latin1')); at >= 0; at = missing.indexOf(Buffer.from('ispe', 'latin1'), at + 1)) {
  missing.write('ispX', at, 'latin1')
}
writeFileSync(join(out, 'missing-ispe.heic'), missing)

writeFileSync(join(out, 'truncated.heic'), heicBytes.subarray(0, Math.floor(heicBytes.length / 3)))

const meta = await sharp(readFileSync(source)).metadata()
const manifest = {
  schemaVersion: 1,
  createdAt: new Date().toISOString(),
  generator: 'scripts/verification/upgrade-0153-fixtures.ts',
  source: { path: 'source.png', width: meta.width, height: meta.height, sha256: sha256(readFileSync(source)) },
  encoders: {
    heic: 'pillow-heif (libheif) via uv run --python 3.12.15',
    avif: 'sharp/libvips avif(quality 55)',
    jpeg: 'sharp/libvips jpeg(quality 85)',
    pillowHeif: python.trim(),
  },
  samples: Object.fromEntries([
    'photo.heic', 'photo.avif', 'control.jpg', 'decoy-ispe.heic', 'oversized-ispe.heic', 'missing-ispe.heic', 'truncated.heic',
    'small.heic', 'small.avif',
  ].map(name => {
    const bytes = readFileSync(join(out, name))
    const small = name.startsWith('small.')
    return [name, { bytes: bytes.length, sha256: sha256(bytes), width: small ? 800 : WIDTH, height: small ? 600 : HEIGHT }]
  })),
}
writeFileSync(join(out, 'manifest.json'), JSON.stringify(manifest, null, 2) + '\n')
console.log(JSON.stringify({ out, heicBytes: heicBytes.length, encodeCommand, samples: Object.keys(manifest.samples) }, null, 2))
